-- Zaženite po schema.sql. Seed nima uporabnikov; created_by ostane NULL.
-- Šest popisov dvakrat tedensko; za preglednost količine generiramo z SQL vzorcem.
select c.id,p.id, greatest(0, case p.sort_order when 1 then 70-c.rn*9 when 2 then 55-c.rn*6 when 3 then 80-c.rn*11 when 4 then 10-c.rn when 5 then 9-c.rn when 6 then 12-c.rn when 7 then 15-c.rn*2 when 8 then 90-c.rn*10 when 9 then 70-c.rn*9 when 10 then 50-c.rn*5 when 11 then 25-c.rn*3 when 12 then 12-c.rn when 13 then 10-c.rn when 14 then 9-c.rn else 0 end) from public.products p cross join (select id,row_number() over(order by completed_at) rn from public.inventory_counts where notes='Seed') c on conflict do nothing;
